"""Small standard-library decoder backends used by the command line frontend."""
import bz2
import gzip
import zlib


def decode(data: bytes):
    """Return (human-readable format, uncompressed bytes), or None if unsupported.

    Format recognition deliberately uses stream magic; filenames do not influence
    decompression.  gzip.decompress and bz2.decompress both accept concatenated
    members, as the reference utility does for ordinary streams.
    """
    if data.startswith(b'\x1f\x8b'):
        try:
            return 'gzip: Deflate', zlib.decompress(data, 31)
        except (OSError, EOFError, zlib.error, ValueError):
            return 'gzip: Deflate', None
    if data.startswith(b'BZh'):
        try:
            return 'bz2: bzip2', bz2.BZ2Decompressor().decompress(data)
        except (OSError, EOFError, ValueError):
            return 'bz2: bzip2', None
    return None
"""Format identification helpers for Ancient's command line interface."""

def identify(data: bytes):
    """Return Ancient's human-readable compression description, or None."""
    if data.startswith(b'\x1f\x8b'):
        return 'gzip: Deflate'
    if data.startswith(b'BZh') and len(data) >= 4 and data[3:4] in b'123456789':
        return 'bz2: bzip2'
    # Unix pack has a compact Huffman header following its two-byte magic.
    if data.startswith(b'\x1f\x1e') and len(data) >= 3:
        return 'z: Pack'
    # Unix compress format (old and block-mode LZW variants).
    if data.startswith((b'\x1f\x9d', b'\x1f\xa0')) and len(data) >= 3:
        return 'Z: Compress'
    if data.startswith(b'XPKF') and len(data) >= 36:
        return 'XPK: XPK'
    if data.startswith(b'RNC\x01'):
        return 'RNC: Rob Northen Compressor (RNC1)'
    if data.startswith(b'RNC\x02'):
        return 'RNC: Rob Northen Compressor (RNC2)'
    if data.startswith(b'DMS!'):
        return 'DMS: Disk Masher System'
    if data.startswith(b'ziRCONia'):
        return 'MMCMP: Music Module Compressor'
    if data.startswith(b'PP20'):
        return 'PowerPacker'
    if data.startswith(b'ICE!'):
        return 'Pack-Ice'
    return None

