import bz2
import gzip
import zlib
import unixcompress


def decode(data: bytes):
    """Return (human-readable format, uncompressed bytes), or None if unsupported.

    Format recognition deliberately uses stream magic; filenames do not influence
    decompression.  gzip.decompress and bz2.decompress both accept concatenated
    members, as the reference utility does for ordinary streams.
    """
    if data.startswith(b'\x1f\x8b'):
        try:
            # Ancient rejects incomplete streams, junk after the last member,
            # and members which produce no bytes.  Decode the first member,
            # while validating any following members as well.
            rest = data
            first = None
            while rest:
                if not rest.startswith(b'\x1f\x8b'):
                    return None
                dec = zlib.decompressobj(16 + zlib.MAX_WBITS)
                plain = dec.decompress(rest) + dec.flush()
                if not dec.eof:
                    return None
                if first is None:
                    first = plain
                rest = dec.unused_data
            if not first:
                return None
            return 'gzip: Deflate', first
        except (OSError, EOFError, zlib.error, ValueError):
            return None
    if data.startswith(b'BZh'):
        # Ancient only treats the signature as a bzip stream when the
        # mandatory block-size digit is present and in range.
        if len(data) < 4 or data[3:4] not in b'123456789':
            return None
