            decompress(data)
            return 'Z: Compress (new)' if data[2] & 0x80 else 'Z: Compress (old)'
        except Exception:
            pass
    if data.startswith(b'\x1f\xa0') and len(data) >= 4:
        return 'SCO Compress LZH'
    return None
