def decode(data: bytes):
    """Return (human-readable format, uncompressed bytes), or None if unsupported.

    Format recognition deliberately uses stream magic; filenames do not influence
    decompression.  gzip.decompress and bz2.decompress both accept concatenated
    members, as the reference utility does for ordinary streams.
    """
    if data.startswith(b'\x1f\x8b'):
        result = _gzip_decode(data)
        if isinstance(result, GzipVerifyError):
            return 'gzip: Deflate', result
        if result is None:
            return 'gzip: Deflate', None
        return 'gzip: Deflate', result
    if data.startswith(b'BZh'):
        # Ancient only treats the signature as a bzip stream when the
        # mandatory block-size digit is present and in range.
        if len(data) < 4 or data[3:4] not in b'123456789':
