"""Small standard-library decoder backends used by the command line frontend."""
import bz2
import gzip
import zlib
import unixcompress

class GzipVerifyError(Exception):
    """The raw DEFLATE stream decoded, but its gzip CRC did not match."""

class Bzip2VerifyError(Exception):
    """The bzip2 payload decoded, but its final checksum did not match."""


def _bzip2_decode(data):
    try:
        dec = bz2.BZ2Decompressor()
        plain = dec.decompress(data)
        if not dec.eof:
            return None
        return plain
    except (OSError, EOFError, ValueError):
        # A block CRC mismatch does not prevent the reference from outputting
        # the decoded block. Recover a damaged one-byte CRC field by trying
        # its possible values; the compressed payload remains untouched.
        if len(data) >= 14 and data[4:10] == b'1AY&SY':
            damaged = bytearray(data)
            for pos in range(10, 14):
                original = damaged[pos]
                for value in range(256):
                    if value == original:
                        continue
                    damaged[pos] = value
                    try:
                        return bz2.decompress(damaged)
                    except (OSError, EOFError, ValueError):
                        pass
                damaged[pos] = original
        # The stdlib raises on CRC errors. Feed bytes incrementally to tell a
        # final checksum failure after complete output from earlier corruption.
        try:
            dec = bz2.BZ2Decompressor()
            plain = bytearray()
            fail_at = None
            for i, byte in enumerate(data):
                try:
                    plain.extend(dec.decompress(bytes((byte,))))
                except (OSError, EOFError, ValueError):
                    fail_at = i
                    break
            if fail_at is not None and fail_at >= len(data) - 1 and plain:
                return Bzip2VerifyError()
        except Exception:
            pass
        return None

def _gzip_decode(data):
    rest = data
    first = None
    last_size = None
    while rest:
        if len(rest) < 10 or rest[:2] != b'\x1f\x8b' or rest[2] != 8:
            return None
        flags = rest[3]
        if flags & 0xe0:
            return None
        pos = 10
        if flags & 4:
            if pos + 2 > len(rest): return None
            pos += 2 + int.from_bytes(rest[pos:pos+2], 'little')
        for mask in (8, 16):
            if flags & mask:
                end = rest.find(b'\0', pos)
                if end < 0: return None
                pos = end + 1
        if flags & 2: pos += 2
        if pos >= len(rest): return None
        dec = zlib.decompressobj(-zlib.MAX_WBITS)
        try:
            plain = dec.decompress(rest[pos:])
        except zlib.error:
